#pragma once
// CSCI 41 -- Lab 08: Stacks and Queues
//
// PROVIDED. Do not edit this file. Implement the functions in
// src/quack.cpp.
//
// A Quack is a double-ended queue of ints on a circular array buffer that
// grows when it runs out of room. Push and pop at EITHER end, all in
// Theta(1) amortised. It is a stack from either end and a queue across.
//
// THE REPRESENTATION, stated once so every rule below is unambiguous:
//
//   data_        a block of capacity_ ints, allocated with new[]
//   capacity_    how many fit before it must grow. Always >= 1.
//   size_        how many are actually in it. 0 <= size_ <= capacity_.
//   frontIndex_  the physical index of the logical FIRST element.
//                Meaningless when size_ == 0, but must stay in range.
//
//   The element at logical position k (0 <= k < size_) lives at physical
//   index (frontIndex_ + k) % capacity_. That is what physicalIndex() is
//   for, and it is the only piece of arithmetic in this whole lab.
//
// Those four lines are the class invariant. Assert them while you work.
//
// A NOTE ON capacity(): it is in the interface so the tests can watch
// growth happen, and so you can watch it too. It is not part of what a
// deque MEANS -- it is an artifact of storing one in an array. Day 21
// called that an abstraction leak, and this one is deliberate.

#include <vector>

class Quack {
public:
    Quack();
    explicit Quack(int initialCapacity);   // PRECONDITION: initialCapacity > 0

    // Rule of Three (Day 10). This class owns its buffer, so the
    // compiler's versions are wrong and you must write all three.
    Quack(const Quack& other);
    Quack& operator=(const Quack& other);
    ~Quack();

    bool empty() const;
    int  size() const;
    int  capacity() const;        // see the note above

    // ---- Part A: the four ends ------------------------------------------
    // Push onto the front or the back. Grow first if there is no room.
    void pushFront(int value);
    void pushBack(int value);

    // Pop from the front or the back. Return false and change nothing when
    // the Quack is empty.
    bool popFront(int& out);
    bool popBack(int& out);

    // ---- Part B: looking without taking ---------------------------------
    // Return false when empty. Do NOT modify the Quack.
    bool peekFront(int& out) const;
    bool peekBack(int& out) const;

    // ---- Part C: the one it is named after ------------------------------
    // Remove BOTH ends at once: the front into frontOut, the back into
    // backOut. Returns false and changes nothing when size() < 2.
    //
    // With exactly two elements this empties the Quack.
    bool quack(int& frontOut, int& backOut);

    // ---- Part D: housekeeping -------------------------------------------
    // Remove everything. The Quack must still be usable afterwards. You may
    // keep the buffer you already have.
    void clear();

    // The contents in logical order, front first. Empty when empty.
    // Does not modify the Quack. Provided for testing and for your own
    // sanity; write it early.
    std::vector<int> toVector() const;

private:
    int* data_;
    int  capacity_;
    int  size_;
    int  frontIndex_;

    // The physical index of logical position `logicalOffset`.
    // PRECONDITION: 0 <= logicalOffset < capacity_.
    int physicalIndex(int logicalOffset) const;

    // Double the capacity and move the contents across.
    //
    // THIS IS THE INTERESTING ONE. When the contents are wrapped, the
    // occupied region is in TWO pieces -- some at the end of the array and
    // some at the start -- so a straight copy would copy the empty middle
    // and split your data. Un-wrap as you copy, and reset frontIndex_.
    void grow();
};
